% definition of parameters
muB = 9.2740100783e-24;
hbar = 1.05457182e-34;
gperp = 2;
gparalell = -18.225;
gtensor = [
    gperp, 0, 0;
    0, gparalell, 0;
    0, 0, gperp];
dg = abs(gperp-gparalell);
rho = 5275.8;
W = 30e-9;
A = W*W;
Iy = A^2/12;
I = 2*Iy;
mu = 4.5962E10;
C = 0.13976323261691082*A^2*mu;
ld = 30e-9;
E=1.2983E11;
bx = [1;0;0];
by = [0;1;0];
bz = [0;0;1];



% Read raw data generated by comsol project
dispersion = read_comsol_file('modes.txt');
Nmodes = max(dispersion(:, 7));

% PLot the dispersion relation (Fig. 3 in manuscript)
plot_dispersions(dispersion, Nmodes);
qq = linspace(0,max(abs(dispersion(:,2))),100);
fL = qq*sqrt(E/rho)/2/pi;
fT = qq*sqrt(C/rho/I)/2/pi;
fF = qq.^2*sqrt(E*Iy/rho/A)/2/pi;
hold on;
plot(qq*1e-9,fL*1e-9, 'LineWidth',3, 'Color', 'magenta');
plot(qq*1e-9,fT*1e-9, 'LineWidth',3, 'Color', 'blue');
plot(qq*1e-9,fF*1e-9, 'LineWidth',3, 'Color', 'red');
hold off;
ylim([0,70]);
box on
exportgraphics(gcf,'dispersion.pdf','ContentType','vector')


