Gammafy = (omegaL.^6*hbar^4/rho/A/E^3/Iy^3).^(1/4)*dg^2/gparalell^2/8.*exp(-omegaL.*ld^2/2*sqrt(rho*A/E/Iy));
Gammaty = hbar*omegaL*dg^2/4/gparalell^2/sqrt(rho*I*C).*exp(-omegaL.^2*ld^2*rho*I/2/C);
Gammay = Gammafy+Gammaty;
