Gammafz = (dg^8*hbar^6*omegaL.^6/gperp^8/hbar^2/rho/A/E^3/Iy^3).^(1/4)/8.*exp(-omegaL.*ld^2/2*sqrt(rho*A/E/Iy));
plot_with_inf(ff, Gammafz, '--')
xlabel('Larmor frequency, $f_\mathrm{L}$ (GHz)', 'Interpreter', 'latex', 'FontName', 'Times');
